{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01KkMPBNSZUYTpypYiGgGniQ","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"\\\\\\\"\\\\\\\"\\\\\\\"Batch lead-lag analysis for distributional canary collapse experiments.\\\\n\\\\nReads all_metrics.json from an experiment directory, runs 5-method lead-lag\\\\nanalysis on all canary-diversity pairs, computes K>=4 consensus, and optionally\\\\nruns full MMCT if null directories are provided.\\\\n\\\\nUsage:\\\\n    python batch_analysis.py --exp_dir results/alpha_sweep/a010_s43_bf16\\\\n    python batch_analysis.py --exp_dir results/alpha_sweep/a010_s43_bf16 \\\\\\\\\\\\n        --null_dirs results/alpha_sweep/a000_s42 results/alpha_sweep/a000_s43\\\\n\\\\nInput:  {exp_dir}/all_metrics.json\\\\nOutput: {exp_dir}/analysis_results.json (or --output path)\\\\n\\\\nDependencies: numpy, scipy, statsmodels\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\n\\\\nimport argparse\\\\nimport json\\\\nimport os\\\\nimport sys\\\\nimport traceback\\\\nimport numpy as np\\\\nfrom scipy import stats\\\\nfrom statsmodels.tsa.stattools import adfuller\\\\n\\\\nN_PERM = 5000\\\\nALPHA_SIG = 0.05\\\\n\\\\nCANARIES = [\\\\\\\"token_entropy\\\\\\\", \\\\\\\"ece\\\\\\\"]\\\\nDOWNSTREAMS = [\\\\\\\"distinct_1\\\\\\\", \\\\\\\"distinct_2\\\\\\\", \\\\\\\"distinct_3\\\\\\\", \\\\\\\"mauve\\\\\\\"]\\\\n\\\\nHIGHER_IS_WORSE = {\\\\\\\"ece\\\\\\\", \\\\\\\"perplexity\\\\\\\"}\\\\nLOWER_IS_WORSE = {\\\\\\\"token_entropy\\\\\\\", \\\\\\\"distinct_1\\\\\\\", \\\\\\\"distinct_2\\\\\\\", \\\\\\\"distinct_3\\\\\\\", \\\\\\\"mauve\\\\\\\"}\\\\n\\\\nALL_METRICS = [\\\\\\\"token_entropy\\\\\\\", \\\\\\\"ece\\\\\\\", \\\\\\\"perplexity\\\\\\\", \\\\\\\"distinct_1\\\\\\\", \\\\\\\"distinct_2\\\\\\\",\\\\n               \\\\\\\"distinct_3\\\\\\\", \\\\\\\"effective_rank\\\\\\\", \\\\\\\"mauve\\\\\\\"]\\\\n\\\\n\\\\ndef load_series(data_dir):\\\\n    path = os.path.join(data_dir, \\\\\\\"all_metrics.json\\\\\\\")\\\\n    with open(path) as f:\\\\n        data = json.load(f)\\\\n    data.sort(key=lambda x: x[\\\\\\\"generation\\\\\\\"])\\\\n    out = {}\\\\n    for k in ALL_METRICS:\\\\n        vals = []\\\\n        for d in data:\\\\n            v = d.get(k)\\\\n            vals.append(v if v is not None else np.nan)\\\\n        out[k] = np.array(vals, dtype=float)\\\\n    return out, len(data)\\\\n\\\\n\\\\ndef orient(series, name):\\\\n    return -series.copy() if name in LOWER_IS_WORSE else series.copy()\\\\n\\\\n\\\\ndef compute_drift(series_dict, n_gens):\\\\n    drift = {}\\\\n    for k in ALL_METRICS:\\\\n        s = series_dict.get(k)\\\\n        if s is None or len(s) < 2:\\\\n            drift[k] = None\\\\n            continue\\\\n        v0, v_last = s[0], s[-1]\\\\n        if abs(v0) < 1e-12:\\\\n            drift[k] = None\\\\n        else:\\\\n            drift[k] = round(float((v_last - v0) / abs(v0) * 100), 2)\\\\n    return drift\\\\n\\\\n\\\\ndef bh_fdr(p_values, alpha=0.05):\\\\n    pv = np.array(p_values, dtype=float)\\\\n    n = len(pv)\\\\n    valid = ~np.isnan(pv)\\\\n    adjusted = np.full(n, np.nan)\\\\n    if valid.sum() == 0:\\\\n        return adjusted.tolist(), [False] * n\\\\n    idx = np.where(valid)[0]\\\\n    p_valid = pv[idx]\\\\n    sorted_idx = np.argsort(p_valid)\\\\n    ranks = np.empty_like(sorted_idx)\\\\n    ranks[sorted_idx] = np.arange(1, len(p_valid) + 1)\\\\n    m = len(p_valid)\\\\n    adj = p_valid * m / ranks\\\\n    adj_sorted = adj[sorted_idx].copy()\\\\n    for i in range(m - 2, -1, -1):\\\\n        adj_sorted[i] = min(adj_sorted[i], adj_sorted[i + 1])\\\\n    adj_sorted = np.minimum(adj_sorted, 1.0)\\\\n    adj_final = np.empty(m)\\\\n    adj_final[sorted_idx] = adj_sorted\\\\n    for i, ix in enumerate(idx):\\\\n        adjusted[ix] = adj_final[i]\\\\n    significant = [(adjusted[i] < alpha if not np.isnan(adjusted[i]) else False) for i in range(n)]\\\\n    return adjusted.tolist(), significant\\\\n\\\\n\\\\n# ── Method 1: Naive cross-correlation ──\\\\n\\\\ndef naive_xcorr(c, d, cn, dn, max_lag=5):\\\\n    x, y = orient(c, cn), orient(d, dn)\\\\n    n = len(x)\\\\n    if np.any(np.isnan(x)) or np.any(np.isnan(y)):\\\\n        return {\\\\\\\"method\\\\\\\": \\\\\\\"naive_xcorr\\\\\\\", \\\\\\\"peak_lag\\\\\\\": None, \\\\\\\"r\\\\\\\": None,\\\\n                \\\\\\\"p_value\\\\\\\": None, \\\\\\\"significant\\\\\\\": False, \\\\\\\"note\\\\\\\": \\\\\\\"NaN in data\\\\\\\"}\\\\n    best_lag, best_r, best_p = 0, 0.0, 1.0\\\\n    for lag in range(-max_lag, max_lag + 1):\\\\n        if lag >= 0:\\\\n            a, b = x[lag:], y[:n - lag]\\\\n        else:\\\\n            a, b = x[:n + lag], y[-lag:]\\\\n        if len(a) < 4:\\\\n            continue\\\\n        if np.std(a) < 1e-12 or np.std(b) < 1e-12:\\\\n            continue\\\\n        r, p = stats.pearsonr(a, b)\\\\n        if abs(r) > abs(best_r):\\\\n            best_lag, best_r, best_p = lag, r, p\\\\n    return {\\\\n        \\\\\\\"method\\\\\\\": \\\\\\\"naive_xcorr\\\\\\\",\\\\n        \\\\\\\"peak_lag\\\\\\\": int(best_lag),\\\\n        \\\\\\\"r\\\\\\\": round(float(best_r), 4),\\\\n        \\\\\\\"p_value\\\\\\\": round(float(best_p), 6),\\\\n        \\\\\\\"significant\\\\\\\": bool(best_p < ALPHA_SIG),\\\\n    }\\\\n\\\\n\\\\n# ── Method 2: Differenced cross-correlation ──\\\\n\\\\ndef diff_xcorr(c, d, cn, dn, max_lag=5):\\\\n    x, y = orient(c, cn), orient(d, dn)\\\\n    if np.any(np.isnan(x)) or np.any(np.isnan(y)):\\\\n        return {\\\\\\\"method\\\\\\\": \\\\\\\"diff_xcorr\\\\\\\", \\\\\\\"peak_lag\\\\\\\": None, \\\\\\\"r\\\\\\\": None,\\\\n                \\\\\\\"p_value\\\\\\\": None, \\\\\\\"significant\\\\\\\": False, \\\\\\\"note\\\\\\\": \\\\\\\"NaN in data\\\\\\\"}\\\\n    dx, dy = np.diff(x), np.diff(y)\\\\n    n = len(dx)\\\\n    best_lag, best_r, best_p = 0, 0.0, 1.0\\\\n    for lag in range(-max_lag, max_lag + 1):\\\\n        if lag >= 0:\\\\n            a, b = dx[lag:], dy[:n - lag]\\\\n        else:\\\\n            a, b = dx[:n + lag], dy[-lag:]\\\\n        if len(a) < 4:\\\\n            continue\\\\n        if np.std(a) < 1e-12 or np.std(b) < 1e-12:\\\\n            continue\\\\n        r, p = stats.pearsonr(a, b)\\\\n        if abs(r) > abs(best_r):\\\\n            best_lag, best_r, best_p = lag, r, p\\\\n    return {\\\\n        \\\\\\\"method\\\\\\\": \\\\\\\"diff_xcorr\\\\\\\",\\\\n        \\\\\\\"peak_lag\\\\\\\": int(best_lag),\\\\n        \\\\\\\"r\\\\\\\": round(float(best_r), 4),\\\\n        \\\\\\\"p_value\\\\\\\": round(float(best_p), 6),\\\\n        \\\\\\\"significant\\\\\\\": bool(best_p < ALPHA_SIG),\\\\n    }\\\\n\\\\n\\\\n# ── Method 3: Threshold onset detection ──\\\\n\\\\ndef threshold_onset(c, d, cn, dn, sigma_mult=3):\\\\n    x, y = orient(c, cn), orient(d, dn)\\\\n    if np.any(np.isnan(x)) or np.any(np.isnan(y)):\\\\n        return {\\\\\\\"method\\\\\\\": \\\\\\\"threshold_onset\\\\\\\", \\\\\\\"onset_canary\\\\\\\": None,\\\\n                \\\\\\\"onset_downstream\\\\\\\": None, \\\\\\\"lead_time\\\\\\\": None, \\\\\\\"significant\\\\\\\": False,\\\\n                \\\\\\\"note\\\\\\\": \\\\\\\"NaN in data\\\\\\\"}\\\\n    gen0_c, gen0_d = x[0], y[0]\\\\n    std_c = np.std(np.diff(x)) if len(x) > 1 else 1e-12\\\\n    std_d = np.std(np.diff(y)) if len(y) > 1 else 1e-12\\\\n    if std_c < 1e-12:\\\\n        std_c = abs(gen0_c) * 0.01 if abs(gen0_c) > 1e-12 else 1e-6\\\\n    if std_d < 1e-12:\\\\n        std_d = abs(gen0_d) * 0.01 if abs(gen0_d) > 1e-12 else 1e-6\\\\n    thresh_c = gen0_c + sigma_mult * std_c\\\\n    thresh_d = gen0_d + sigma_mult * std_d\\\\n    onset_c, onset_d = None, None\\\\n    for i in range(1, len(x)):\\\\n        if onset_c is None and x[i] > thresh_c:\\\\n            onset_c = i\\\\n        if onset_d is None and y[i] > thresh_d:\\\\n            onset_d = i\\\\n    if onset_c is not None and onset_d is not None:\\\\n        lead = onset_d - onset_c\\\\n        significant = lead > 0\\\\n    elif onset_c is not None and onset_d is None:\\\\n        lead = len(x) - onset_c\\\\n        significant = True\\\\n    else:\\\\n        lead = 0\\\\n        significant = False\\\\n    return {\\\\n        \\\\\\\"method\\\\\\\": \\\\\\\"threshold_onset\\\\\\\",\\\\n        \\\\\\\"onset_canary\\\\\\\": onset_c,\\\\n        \\\\\\\"onset_downstream\\\\\\\": onset_d,\\\\n        \\\\\\\"lead_time\\\\\\\": int(lead) if lead is not None else None,\\\\n        \\\\\\\"significant\\\\\\\": significant,\\\\n    }\\\\n\\\\n\\\\n# ── Method 4: Permutation Granger ──\\\\n\\\\ndef _build_lag_matrix(y, x, max_lag):\\\\n    T = len(y)\\\\n    n = T - max_lag\\\\n    Y = y[max_lag:]\\\\n    cols_r = [np.ones(n)]\\\\n    for lag in range(1, max_lag + 1):\\\\n        cols_r.append(y[max_lag - lag: T - lag])\\\\n    cols_u = list(cols_r)\\\\n    for lag in range(1, max_lag + 1):\\\\n        cols_u.append(x[max_lag - lag: T - lag])\\\\n    return Y, np.column_stack(cols_r), np.column_stack(cols_u)\\\\n\\\\n\\\\ndef _granger_f_stat(y, x, max_lag):\\\\n    Y, X_r, X_u = _build_lag_matrix(y, x, max_lag)\\\\n    n = len(Y)\\\\n    q = max_lag\\\\n\\\", \\\"stderr\\\": \\\"\\\", \\\"return_code\\\": 0}, \\\"error\\\": null, \\\"metadata\\\": {\\\"elapsed_seconds\\\": 5.74}}\"}"}]},"parent_tool_use_id":"toolu_018KYUeKAeSMQrGmBcStabsZ","session_id":"d1dedad6-d763-4570-8bc0-74b69b0c05e8","uuid":"da4c55d5-5f5c-4828-8219-3b978d1092b4","timestamp":"2026-05-20T01:04:18.794Z"}
