{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_019A3YGYbzLvQesESRpb5atZ","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_011voycPU1vWpK7nL6HJSsix","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"westd-17855","command":"cat << 'PYEOF' > /tmp/compute_d105_d111.py\nimport json, os, sys\nimport numpy as np\n\nLOWER_IS_WORSE = {'token_entropy', 'distinct_1', 'distinct_2', 'distinct_3', 'mauve'}\nBASE = '/root/autodl-tmp/distrib_canary_collapse/results'\n\nEXPERIMENTS = {\n    '0.05': 'alpha_sweep/a005_s42_fp32_v3_d080',\n    '0.10': 'alpha_sweep/a010_s42_fp32',\n    '0.25': 'alpha_sweep/a025_s42_fp32',\n    '0.30': 'alpha_sweep/a030_s42_fp32',\n    '0.35': 'alpha_sweep/a035_s42_fp32',\n    '0.40': 'alpha_sweep/a040_s42_fp32',\n    '0.45': 'alpha_sweep/a045_s42_fp32',\n    '0.50': 'alpha_sweep/a050_s42_fp32',\n    '0.60': 'alpha_sweep/a060_s42_fp32_v3_d080',\n    '0.75': 'alpha_sweep/a075_s42_fp32',\n    '1.00': 'padding_robustness/a100_s42_fp32',\n}\n\nCANARIES = ['token_entropy', 'ece']\nDOWNSTREAMS = ['distinct_1', 'distinct_2', 'distinct_3', 'mauve']\n\ndef orient(series, name):\n    s = np.array(series, dtype=float)\n    if name in LOWER_IS_WORSE:\n        s = -s\n    return s\n\ndef onset_gen_3sigma(series, name):\n    \"\"\"D105-correct: std of entire oriented series, base=s[0], thresh=base+3*sigma\"\"\"\n    s = orient(series, name)\n    base = s[0]\n    sigma = np.std(s)\n    if sigma < 1e-12:\n        return None\n    thresh = base + 3 * sigma\n    for i in range(1, len(s)):\n        if s[i] > thresh:\n            return i\n    return None\n\ndef threshold_lead_3sigma(c_series, d_series, cn, dn):\n    co = onset_gen_3sigma(c_series, cn)\n    do_val = onset_gen_3sigma(d_series, dn)\n    if co is None or do_val is None:\n        return {\n            'canary_onset': int(co) if co is not None else None,\n            'downstream_onset': int(do_val) if do_val is not None else None,\n            'lead_time': None,\n            'significant': False\n        }\n    lt = do_val - co\n    return {\n        'canary_onset': int(co),\n        'downstream_onset': int(do_val),\n        'lead_time': int(lt),\n        'significant': bool(lt > 0)\n    }\n\ndef bh_fdr(pvals, alpha=0.05):\n    n = len(pvals)\n    indexed = sorted(enumerate(pvals), key=lambda x: x[1])\n    adjusted = [0.0] * n\n    sig = [False] * n\n    prev = 1.0\n    for rank_idx in range(n - 1, -1, -1):\n        orig_idx, p = indexed[rank_idx]\n        rank = rank_idx + 1\n        adj_p = min(prev, p * n / rank)\n        adjusted[orig_idx] = adj_p\n        sig[orig_idx] = adj_p <= alpha\n        prev = adj_p\n    return adjusted, sig\n\ndef extract_series(metrics_data, metric_name):\n    return [g[metric_name] for g in metrics_data]\n\ndef process_experiment(alpha_str, exp_dir):\n    full_dir = os.path.join(BASE, exp_dir)\n    \n    # Load all_metrics.json\n    metrics_path = os.path.join(full_dir, 'all_metrics.json')\n    with open(metrics_path) as f:\n        metrics_data = json.load(f)\n    \n    # Load analysis_results.json\n    analysis_path = os.path.join(full_dir, 'analysis_results.json')\n    analysis_5m_path = os.path.join(full_dir, 'analysis', '5method_leadlag.json')\n    \n    analysis = None\n    if os.path.exists(analysis_path):\n        with open(analysis_path) as f:\n            analysis = json.load(f)\n    elif os.path.exists(analysis_5m_path):\n        with open(analysis_5m_path) as f:\n            analysis = json.load(f)\n    \n    # Build lookup from pair_details\n    pair_lookup = {}\n    if analysis and 'pair_details' in analysis:\n        for pd in analysis['pair_details']:\n            key = f\"{pd['canary']}_vs_{pd['downstream']}\"\n            pair_lookup[key] = pd['results']\n    elif analysis and 'forward' in analysis:\n        pair_lookup = analysis['forward']\n    \n    results = {}\n    pair_order = []\n    \n    for cn in CANARIES:\n        for dn in DOWNSTREAMS:\n            pair_key = f\"{cn}_vs_{dn}\"\n            pair_order.append(pair_key)\n            \n            pr = {\n                'canary': cn, 'downstream': dn,\n                'naive_peak_lag': None, 'naive_sig': False, 'naive_fwd': False,\n                'diff_peak_lag': None, 'diff_sig_fdr': False, 'diff_fwd': False,\n                'thresh_co': None, 'thresh_do': None, 'thresh_lt': None, 'thresh_sig': False,\n                'permG_sig_fdr': False,\n                'ty_pval': 1.0, 'ty_sig_raw': False, 'ty_chi2': None,\n            }\n            \n            # Get from analysis\n            if pair_key in pair_lookup:\n                r = pair_lookup[pair_key]\n                \n                # Naive\n                naive = r.get('naive_xcorr', {})\n                pr['naive_peak_lag'] = naive.get('peak_lag')\n                pr['naive_sig'] = naive.get('significant', False)\n                \n                # Diff\n                diff = r.get('diff_xcorr', {})\n                pr['diff_peak_lag'] = diff.get('peak_lag')\n                pr['diff_sig_fdr'] = diff.get('significant_fdr', diff.get('significant', False))\n                \n                # PermG\n                pg = r.get('perm_granger_fwd', r.get('perm_granger', {}))\n                pr['permG_sig_fdr'] = pg.get('significant_fdr', pg.get('significant', False))\n                \n                # TY\n                ty = r.get('ty_granger', {})\n                pr['ty_pval'] = ty.get('p_value', 1.0)\n                pr['ty_sig_raw'] = ty.get('significant', False)\n                pr['ty_chi2'] = ty.get('chi2')\n            \n            # D105: Compute 3sigma threshold onset from raw series\n            c_series = extract_series(metrics_data, cn)\n            d_series = extract_series(metrics_data, dn)\n            thresh = threshold_lead_3sigma(c_series, d_series, cn, dn)\n            pr['thresh_co'] = thresh['canary_onset']\n            pr['thresh_do'] = thresh['downstream_onset']\n            pr['thresh_lt'] = thresh['lead_time']\n            pr['thresh_sig'] = thresh['significant']\n            \n            # D111: peak_lag > 0 for naive and diff\n            pr['naive_fwd'] = bool(\n                pr['naive_sig'] and\n                pr['naive_peak_lag'] is not None and\n                pr['naive_peak_lag'] > 0\n            )\n            pr['diff_fwd'] = bool(\n                pr['diff_sig_fdr'] and\n                pr['diff_peak_lag'] is not None and\n                pr['diff_peak_lag'] > 0\n            )\n            \n            results[pair_key] = pr\n    \n    # BH FDR on TY p-values across 8 pairs\n    ty_pvals = [results[k]['ty_pval'] if results[k]['ty_pval'] is not None else 1.0 for k in pair_order]\n    adj_pvals, sig_fdr = bh_fdr(ty_pvals, alpha=0.05)\n    for i, k in enumerate(pair_order):\n        results[k]['ty_pfdr'] = adj_pvals[i]\n        results[k]['ty_sig_fdr'] = sig_fdr[i]\n    \n    # Count per method\n    counts = {\n        'naive': sum(results[k]['naive_fwd'] for k in pair_order),\n        'diff': sum(results[k]['diff_fwd'] for k in pair_order),\n        'threshold': sum(results[k]['thresh_sig'] for k in pair_order),\n        'perm_granger': sum(results[k]['permG_sig_fdr'] for k in pair_order),\n        'ty_granger': sum(results[k]['ty_sig_fdr'] for k in pair_order),\n    }\n    \n    # Consensus per pair\n    consensus = {}\n    for k in pair_order:\n        r = results[k]\n        votes = sum([\n            int(r['naive_fwd']),\n            int(r['diff_fwd']),\n            int(r['thresh_sig']),\n            int(r['permG_sig_fdr']),\n            int(r['ty_sig_fdr']),\n        ])\n        consensus[k] = votes\n    \n    k_vals = list(consensus.values())\n    \n    return {\n        'alpha': alpha_str,\n        'n_gen': len(metrics_data),\n        'pairs': results,\n        'counts': counts,\n        'consensus': consensus,\n        'K_ge3': sum(1 for v in k_vals if v >= 3),\n        'K_ge4': sum(1 for v in k_vals if v >= 4),\n