eam_onset\\\": do, \\\"lead_time\\\": None, \\\"significant\\\": False}\\n    lt = do - co\\n    return {\\\"canary_onset\\\": int(co), \\\"downstream_onset\\\": int(do), \\\"lead_time\\\": int(lt), \\\"significant\\\": bool(lt > 0)}\\n\\n\\ndef onset_gen_2sigma(series, name):\\n    s = orient(series, name)\\n    base, sigma = s[0], np.std(s)\\n    if sigma < 1e-12:\\n        return None\\n    thresh = base + 2 * sigma\\n    for i in range(1, len(s)):\\n        if s[i] > thresh:\\n            return i\\n    return None\\n\\n\\ndef assemble_metrics(exp_dir):\\n    all_path = os.path.join(exp_dir, \\\"all_metrics.json\\\")\\n    if os.path.exists(all_path):\\n        with open(all_path) as f:\\n            return json.load(f)\\n    metrics = []\\n    gen_idx = 0\\n    while True:\\n        mpath = os.path.join(exp_dir, f\\\"gen_{gen_idx}\\\", \\\"metrics.json\\\")\\n        if not os.path.exists(mpath):\\n            break\\n        with open(mpath) as f:\\n            m = json.load(f)\\n        m[\\\"generation\\\"] = gen_idx\\n        metrics.append(m)\\n        gen_idx += 1\\n    return sorted(metrics, key=lambda x: x[\\\"generation\\\"]) if metrics else None\\n\\n\\ndef get_sig(method_result):\\n    \\\"\\\"\\\"Best available significance: significant_fdr > sig_fdr_permethod > significant.\\\"\\\"\\\"\\n    for key in [\\\"significant_fdr\\\", \\\"sig_fdr_permethod\\\"]:\\n        v = method_result.get(key)\\n        if v is not None:\\n            return bool(v)\\n    return bool(method_result.get(\\\"significant\\\", False))\\n\\n\\ndef extract_sigs_from_5method(json_path, cn, dn):\\n    with open(json_path) as f:\\n        data = json.load(f)\\n    for pair in data[\\\"pairs\\\"]:\\n        if pair[\\\"canary\\\"] == cn and pair[\\\"downstream\\\"] == dn:\\n            fwd = pair[\\\"forward\\\"]\\n            return {\\n                \\\"naive_xcorr\\\": get_sig(fwd[\\\"naive_xcorr\\\"]),\\n                \\\"diff_xcorr\\\": get_sig(fwd[\\\"diff_xcorr\\\"]),\\n                \\\"perm_granger\\\": get_sig(fwd[\\\"perm_granger\\\"]),\\n                \\\"ty_granger\\\": get_sig(fwd[\\\"ty_granger\\\"]),\\n                \\\"perm_granger_rev\\\": get_sig(pair.get(\\\"reverse\\\", {}).get(\\\"perm_granger\\\", {})),\\n            }\\n    return None\\n\\n\\ndef extract_sigs_from_analysis_results(json_path, cn, dn):\\n    with open(json_path) as f:\\n        data = json.load(f)\\n    for pd in data[\\\"pair_details\\\"]:\\n        if pd[\\\"canary\\\"] == cn and pd[\\\"downstream\\\"] == dn:\\n            r = pd[\\\"results\\\"]\\n            return {\\n                \\\"naive_xcorr\\\": get_sig(r.get(\\\"naive_xcorr\\\", {})),\\n                \\\"diff_xcorr\\\": get_sig(r.get(\\\"diff_xcorr\\\", {})),\\n                \\\"perm_granger\\\": get_sig(r.get(\\\"perm_granger_fwd\\\", {})),\\n                \\\"ty_granger\\\": get_sig(r.get(\\\"ty_granger\\\", {})),\\n                \\\"perm_granger_rev\\\": get_sig(r.get(\\\"perm_granger_rev\\\", {})),\\n            }\\n    return None\\n\\n\\ndef configure_experiments(base_dir):\\n    candidates = [\\n        (\\\"scale_69b_a100_s42\\\", \\\"result\\n\\n... [截断: 输出过长，省略 5861 字符] ...\\n\\nts.items():\\n        result = process_experiment(exp_id, exp_info)\\n        if result is None:\\n            print(f\\\"\\\\nSKIPPED {exp_id}: no metrics data\\\")\\n            continue\\n        all_results[exp_id] = result\\n\\n        r = result\\n        print(f\\\"\\\\n{'='*90}\\\")\\n        print(f\\\"{exp_id} [{r['display']}] (T={r['n_gens']}, src={r['format']})\\\")\\n        print(f\\\"{'='*90}\\\")\\n        print(f\\\"  K>=4(3s)={r['k4_3sigma']}/8  K>=3(3s)={r['k3_3sigma']}/8  |  K>=4(2s)={r['k4_2sigma']}/8  K>=3(2s)={r['k3_2sigma']}/8\\\")\\n        print(f\\\"  Naive={r['naive']}/8  DiffX={r['diff_xcorr']}/8  Thr3s={r['threshold_3sigma']}/8  PermG={r['perm_granger_fwd']}/8(rev={r['perm_granger_rev']}/8)  TY={r['ty_granger']}/8\\\")\\n        print(f\\\"\\\\n  {'Pair