  f\\\"{r['k4_3sigma']:>2}/8      {r['k3_3sigma']:>2}/8      \\\"\\n              f\\\"{r['threshold_3sigma']:>2}/8     {r['threshold_2sigma']:>2}/8     {delta:>+3}\\\")\\n\\n    # Save JSON\\n    save_dir = os.path.join(base_dir, \\\"results\\\", \\\"analysis\\\")\\n    os.makedirs(save_dir, exist_ok=True)\\n    save_path = os.path.join(save_dir, \\\"3sigma_recompute_d105_17855.json\\\")\\n\\n    save_data = {}\\n    for exp_id, r in all_results.items():\\n        save_data[exp_id] = {k: v for k, v in r.items() if k != \\\"pairs\\\"}\\n        save_data[exp_id][\\\"per_pair\\\"] = {}\\n        for pk, pv in r[\\\"pairs\\\"].items():\\n            save_data[exp_id][\\\"per_pair\\\"][pk] = {\\n                \\\"k_3sigma\\\": pv[\\\"k_3sigma\\\"], \\\"k_2sigma\\\": pv[\\\"k_2sigma\\\"],\\n                \\\"votes_3s\\\": pv[\\\"votes_3s\\\"],\\n                \\\"threshold_3sigma_onset\\\": pv[\\\"thr_3s\\\"],\\n                \\\"perm_granger_rev\\\": pv[\\\"perm_granger_rev\\\"],\\n            }\\n\\n    with open(save_path, \\\"w\\\") as f:\\n        json.dump({\\n            \\\"timestamp\\\": datetime.now().isoformat(),\\n            \\\"task\\\": \\\"D105\\\",\\n            \\\"config\\\": {\\n                \\\"canaries\\\": CANARIES, \\\"downstreams\\\": DOWNSTREAMS,\\n                \\\"n_pairs\\\": 8, \\\"threshold_sigma\\\": 3,\\n                \\\"sig_criterion\\\": \\\"fdr_permethod (significant_fdr where available, fallback to significant)\\\",\\n                \\\"note\\\": \\\"method_ablation._onset_gen used 2sigma, now fixed to 3sigma. This recompute uses true 3sigma.\\\",\\n            },\\n            \\\"results\\\": save_data,\\n        }, f, indent=2, cls=NumpyEncoder)\\n    print(f\\\"\\\\nSaved: {save_path}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\", \"stderr\": \"\", \"return_code\": 0}, \"error\": null, \"metadata\": {\"elapsed_seconds\": 0.51}}"}}}
