perm_granger\\\", \\\"f_stat\\\": round(float(f_obs), 4),\\n                \\\"p_value\\\": None, \\\"significant\\\": False}\\n    p = (np.sum(valid >= f_obs) + 1) / (len(valid) + 1)\\n    return {\\n        \\\"method\\\": \\\"perm_granger\\\",\\n        \\\"f_stat\\\": round(float(f_obs), 4),\\n        \\\"p_value\\\": round(float(p), 6),\\n        \\\"significant\\\": bool(p < ALPHA_SIG),\\n    }\\n\\n\\n# ── Method 5: Toda-Yamamoto Granger ──\\n\\ndef _determine_d_max(series, max_d=2, alpha=0.05):\\n    for d in range(max_d + 1):\\n        try:\\n            result = adfuller(series, maxlag=min(3, len(series) // 3 - 1\\n\\n... [截断: 输出过长，省略 9000 字符] ...\\n\\n, null_dirs)\\n        except Exception as e:\\n            print(f\\\"  MMCT failed: {e}\\\")\\n            traceback.print_exc()\\n            mmct_result = {\\\"mode\\\": \\\"weighted_pair_forward\\\", \\\"error\\\": str(e)}\\n    else:\\n        print(\\\"No null_dirs provided, using simple K>=4 consensus as MMCT proxy\\\")\\n        mmct_result = {\\n            \\\"mode\\\": \\\"weighted_pair_forward\\\",\\n            \\\"detection_rate\\\": round(k4 / total, 4) if total > 0 else 0.0,\\n            \\\"note\\\": \\\"simple_consensus_k4 (no null distribution)\\\",\\n        }\\n\\n    # 4. Build output\\n    output = {\\n        \\\"exp_dir\\\": exp_dir,\\n        \\\"n_generations\\\": n_gens,\\n        \\\"drift_pct\\\": drift,\\n        \\\"lead_lag\\\": lead_lag,\\n        \\\"mmct\\\": mmct_result,\\n        \\\"consensus_detail\\\": consensus_counts,\\n        \\\"pair_details\\\": _clean(all_pairs),\\n    }\\n\\n    if output_path is None:\\n        output_path = os.path.join(exp_dir, \\\"analysis_results.json\\\")\\n    os.makedirs(os.path.dirname(output_path) or \\\".\\\", exist_ok=True)\\n    with open(output_path, \\\"w\\\") as f:\\n        json.dump(output, f, indent=2)\\n    print(f\\\"\\\\nSaved: {output_path}\\\")\\n\\n    # Print summary\\n    print(f\\\"\\\\n{'='*60}\\\")\\n    print(